import re


def parse_duration(s):
    """Parse a duration string like '1h30m' into seconds."""
    if not isinstance(s, str):
        return 0

    text = s.strip()
    if not text:
        return 0

    # Accept one or more "<number><unit>" chunks (h/m/s), with optional spaces.
    if not re.fullmatch(r"(?i)(?:\d+\s*[hms]\s*)+", text):
        return 0

    unit_to_seconds = {"h": 3600, "m": 60, "s": 1}
    seen_units = set()
    total_seconds = 0

    for number_text, unit_text in re.findall(r"(?i)(\d+)\s*([hms])", text):
        unit = unit_text.lower()
        if unit in seen_units:
            return 0
        seen_units.add(unit)
        total_seconds += int(number_text) * unit_to_seconds[unit]

    return total_seconds
