import re


def parse_duration(s):
    """Parse a duration string like '1h30m' into seconds."""
    if not isinstance(s, str):
        raise TypeError("duration must be a string")

    s = s.strip()
    if not s:
        raise ValueError("duration cannot be empty")

    parts = re.findall(r"(\d+)([hms])", s)
    if not parts or "".join(f"{value}{unit}" for value, unit in parts) != s:
        raise ValueError(f"invalid duration: {s!r}")

    unit_seconds = {"h": 3600, "m": 60, "s": 1}
    unit_order = {"h": 0, "m": 1, "s": 2}
    seen_units = set()
    last_order = -1
    total_seconds = 0

    for value_text, unit in parts:
        if unit in seen_units:
            raise ValueError(f"repeated unit: {unit}")
        seen_units.add(unit)

        current_order = unit_order[unit]
        if current_order < last_order:
            raise ValueError(f"invalid unit order in duration: {s!r}")
        last_order = current_order

        total_seconds += int(value_text) * unit_seconds[unit]

    return total_seconds
